INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64935939', 64935939, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Penyusunan Rekomendasi Kebijakan Produktivitas atau total factor productivity sebagai pendorong utama pertumbuhan ekonomi', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4', '1. Pengkajian dan Analisis Awal 2. Penyusunan Strategi dan Kerangka Kebijakan 3. Fasilitasi Koordinasi Lintas Sektor 4. Penyusunan Mekanisme Integrasi Perencanaan 5. Penyusunan Dokumen Teknis 6. Dukungan Sinkronisasi Perencanaan 7. Monitoring Substansi dan Konsolidasi Output', 'erdasarkan kebutuhan sumber daya untuk mendukung realisasi kegiatan di Direktorat Perencanaan Peningkatan Produktivitas dan Pembangunan Tematik Tahun Anggaran 2026 dibutuhkan personil yang memiliki keahlian sebagai berikut. 1. Berlatar belakang Pendidikan minimal Strata-2 (S2) di bidang Ilmu Ekonomi, Ekonomi Pembangunan, Studi Pembangunan, Manajemen, Perencanaan Wilayah dan Kota, Manajemen, dan Kebijakan Publik. 2. Memiliki pengalaman kerja profesional minimal 5 tahun dalam bidang yang terkait dengan perencanaan pembangunan, pengukuran dan analisis produktivitas, Total Factor Productivity (TFP), pengembangan kebijakan peningkatan produktivitas, serta koordinasi lintas sektor. 3. Memiliki pemahaman mendalam mengenai isu, tren, konsep, dan kerangka kerja produktivitas serta TFP, serta pernah terlibat aktif dalam kajian atau diskusi teknis di bidang tersebut. 4. MempunyaI kemampuan dan pengalaman terlibat dalam kegiatan penyusunan RPJPN, RPJMN, RKP, kajian kebijakan lintas sektor, sinkronisasi perencanaan atau harmonisasi program K/L, dan perencanaan berbasis risiko. 5. Memiliki pemahaman yang memadai dan penguasaan dalam penyusunan laporan profesional: laporan analitis, policy paper, executive summary, dan laporan akhir. 6. Memiliki kemampuan menyusun analisis konseptual, termasuk kajian produktivitas, framework TFP, dan hubungan antara sektor, serta kinerja pembangunan. 7. Memiliki pemahaman memadai mengenai proses bisnis perencanaan pembangunan nasional dan daerah, termasuk mekanisme monitoring, evaluasi, dan pelaporan dalam konteks program produktivitas.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1822977);
