INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64895571', 64895571, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Analis Pengembangan Inovasi Pendanaan Unit Kerja Staf Ahli Bidang Inovasi Pendanaan Pembangunan Tahun Anggaran 2026', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 125000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Rencana Pembangunan Jangka Menengah Nasional (RPJMN) Tahun 2025–2029 disusun sebagai pedoman pelaksanaan pembangunan nasional menuju visi Indonesia Emas 2045. Kebutuhan investasi untuk mendukung pembangunan infrastruktur, transformasi ekonomi, pembangunan manusia, dan agenda pembangunan berkelanjutan terus meningkat, sementara ketergantungan pemerintah daerah terhadap transfer pusat masih tinggi dan Pendapatan Asli Daerah (PAD) belum dapat menopang pembiayaan pembangunan secara mandiri. Kondisi ini menuntut adanya pendekatan pendanaan yang lebih innovatif, inklusif, dan adaptif agar pembangunan daerah dapat berjalan secara berkelanjutan dan tidak hanya mengandalkan APBD.', 'Konsultan Analis Pengembangan Inovasi Pendanaan bertanggung jawab terhadap pelaksanaan Kajian Inovasi Pendanaan Pembangunan Proyek Prioritas dan Strategis Nasional dalam RPJMN 2025-2029 Berbasis Kolaborasi Multipihak antara lain: 1. Analisis kebijakan nasional dan kondisi ekonomi dan fiskal Indonesia untuk mengidentifikasi kebutuhan peluang dan kesenjangan dalam pendanaan 2. Identifikasi pemangku kepentingan dan peran unsur pentahelix (pemerintah, dunia usaha, akademisi, komunitas, dan media dalam mobilisasi dan pemanfaatan pendanaan inovatif di tingkat daerah 3. Studi praktik baik di dalam/luar negri mengenai penerapan kolaborasi multipihak dalam pemanfaatan skema pendanaan inovatif 4. Perumusan model pendanaan pembangunan berbasis pentahelix approach, yaitu kerangka konseptual kolaborasi multipihak untuk memobilisasi dan memanfaatkan sumber pendanaan non-APBD secara inovatif dan berkelanjutan 5. Identifikasi proyek prioritas dan strategis di daerah daerah kajian untuk pengujian implementatif model pendanaan pembangunan dan kelembagaan berbasis pentahelix approach 6. Formulasi rekomendasi kebijakan dan strategi implementasi untuk memperkuat kapasitas daerah serta optimalisasi pemanfaatan inovasi pendanaan melalui penguatan kolaborasi multipihak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1828531);
